<script>
  import { whenVisible } from "./reveal.js";
  // A drawing of one real Docustay screen, in the Desk look. Everything on it is a thing the product shows; names are sample data (the figure caption says so). Plays once when it comes into view; with reduced motion the stylesheet shows the end state.
  let { kind = "fields", n = 0, form = null, pay = null } = $props(); let run = $state(false);
</script>
<div class="scr k-{kind}" class:run {@attach whenVisible((v) => { if (v) run = true; })} data-screen={kind}>
{#if kind === "fields"}
  <aside><b>Fields</b>{#each ["Signature", "Initials", "Date signed", "Text", "Checkbox", "Dropdown", "Payment"] as f, i}<span style="--d:{i * 70}ms">{f}</span>{/each}</aside>
  <div class="pg"><p class="h4">Services Agreement</p><i></i><i style="width:86%"></i><i style="width:92%"></i><i style="width:60%"></i><i></i><i style="width:78%"></i>
    <em class="fl red" style="--d:500ms;left:8%;top:70%;width:46%">Client signature</em><em class="fl" style="--d:800ms;left:60%;top:70%;width:32%">Date signed</em><em class="fl blue" style="--d:1100ms;left:8%;top:52%;width:40%">Provider signature</em><em class="fl" style="--d:1400ms;left:8%;top:84%;width:26%">Initials</em>
    <u class="chip a">Client</u><u class="chip b">Provider</u></div>
{:else if kind === "board"}
  <div class="tb"><b>Documents</b><span>Sent</span><span>Opened</span><span class="on">Signed</span><span>Declined</span></div>
  {#each [["Services agreement", "Dana W.", "executed", "Executed"], ["Mutual NDA", "Sam O.", "signed", "1 of 2 signed"], ["Lease addendum", "Priya N.", "opened", "Opened"], ["Photo release", "Marcus T.", "sent", "Sent · reminder in 2 days"], ["Offer letter", "Lena K.", "declined", "Declined"]] as r, i}<p class="row" style="--d:{i * 120}ms"><b>{r[0]}</b><span>{r[1]}</span><i class="st {r[2]}">{r[3]}</i><button type="button" tabindex="-1">{r[2] === "executed" || r[2] === "declined" ? "Download" : "Remind"}</button></p>{/each}
{:else if kind === "phone"}
  <div class="ph"><div class="top"><span>Services Agreement</span><u>English ▾</u></div><div class="pg"><i></i><i style="width:80%"></i><i style="width:90%"></i><em class="fl red" style="--d:600ms;left:6%;top:62%;width:60%">Tap to sign</em></div><label class="ck"><s></s> I agree to sign this electronically</label><button type="button" tabindex="-1">Finish</button></div>
{:else if kind === "email"}
  <div class="em"><p class="m"><span>From</span> Northwind Studio &lt;hello@northwind.example&gt;</p><p class="m"><span>Subject</span> Please sign: Services Agreement</p><div class="bd"><p>Dana, Northwind Studio has asked you to review and sign a document.</p><button type="button" tabindex="-1">Review and sign</button><p class="s">The link is yours alone. You do not need an account.</p></div></div>
{:else if kind === "emailtest"}
  <div class="em test"><p class="m"><span>To</span> you@yourcompany.example</p><p class="m"><span>Subject</span> [TEST] Please sign: Services Agreement</p><div class="bd"><p>This is a practice run. The person you named, Rosa Alvarez, was not emailed.</p><button type="button" tabindex="-1">Review and sign</button><p class="s">Every page of the document carries a TEST watermark.</p></div><b class="wm" data-w="TEST" aria-hidden="true"></b></div>
{:else if kind === "certificate"}
  <div class="ct"><p class="h4">Certificate of completion</p><p><span>Document</span> Services Agreement</p><p style="--d:300ms"><span>Signed by</span> Dana Whitfield · 14:02 UTC</p><p style="--d:600ms"><span>Signed by</span> Ada Lovelace · 14:09 UTC</p><p style="--d:900ms"><span>File hash</span> sha-256 9f2c…41ab</p><b class="stamp">SIGNED</b></div>
{:else if kind === "team"}
  <div class="tm"><p class="h"><b>Northwind</b><span>Roles</span></p>{#each [["Ada", "Owner", "Everything, billing, people"], ["Grace", "Admin", "Settings and people"], ["Lin", "Member", "Send and track"]] as r, i}<p class="row" style="--d:{i * 140}ms"><b>{r[0]}</b><i class="st {i ? 'opened' : 'executed'}">{r[1]}</i><span>{r[2]}</span></p>{/each}<p class="h"><b>Teams</b><span>Who sees what</span></p><p class="row"><b>Sales</b><span>Lin, Grace</span></p><p class="row"><b>Onboarding</b><span>Ada, Grace</span></p></div>
{:else if kind === "phone-pay"}
  <div class="ph"><div class="top"><span>Services agreement</span><u>English ▾</u></div><div class="pg"><i></i><i style="width:80%"></i><i style="width:90%"></i><em class="fl" style="--d:600ms;left:6%;top:62%;width:60%">Signed</em></div><label class="ck"><s></s> Signed. Pay to finish.</label><button type="button" tabindex="-1">Pay $600.00 by card</button></div>
{:else if kind === "pay"}
  <div class="pgbox"><p class="h4">{pay?.title ?? "Retainer Agreement"}</p><i></i><i style="width:80%"></i><div class="pay" style="--d:500ms"><b>{pay?.label ?? "Payment"}</b><span>{pay?.amount ?? "$1,500.00 USD"}</span><u>Pay by card</u></div><em class="fl red" style="--d:900ms;position:relative;margin-top:12px;display:block">{pay?.sig ?? "Client signature"} · held until it is paid</em></div>
{:else if kind === "form"}
  <div class="fm"><p class="h4">{form?.title ?? "Contact us"}</p>{#each form?.fields ?? ["Your name", "Email", "What do you need?"] as f, i}<span class="in" style="--d:{i * 160}ms">{f}</span>{/each}<button type="button" tabindex="-1">{form?.button ?? "Submit"}</button><p class="to">Saved to People ✓</p></div>
{:else if kind === "scribe"}
  <div class="sb"><p class="ask">A two-payment services agreement for a web design client</p>{#each ["Asked 3 questions", "Wrote the agreement, 7 sections", "Placed the signature and date fields", "Set 2 payments"] as s, i}<p class="ck2" style="--d:{600 + i * 520}ms"><s></s>{s}</p>{/each}<div class="bt"><b>Review it</b><span>Change something</span></div></div>
{:else if kind === "audit"}
  <div class="au">{#each [["09:14:02", "documents.document.sent", "Ada · key crm-sync"], ["09:31:40", "documents.document.opened", "Dana Whitfield"], ["09:36:18", "documents.document.signed", "Dana Whitfield"], ["09:36:19", "documents.document.executed", "sealed · 9f2c…41ab"]] as r, i}<p class="row" style="--d:{i * 260}ms"><time>{r[0]}</time><b>{r[1]}</b><span>{r[2]}</span></p>{/each}</div>
{:else if kind === "lang"}
  <div class="lg">{#each [["English", "Sign the document", ""], ["Español", "Firmar el documento", "Beta"], ["العربية", "توقيع المستند", "Beta"], ["日本語", "書類に署名する", "Beta"]] as r, i}<p class="row" dir={r[0] === "العربية" ? "rtl" : "ltr"} style="--d:{i * 160}ms"><b>{r[0]}</b><span>{r[1]}</span>{#if r[2]}<i class="st opened">{r[2]}</i>{/if}</p>{/each}</div>
{:else if kind === "usage"}
  <div class="us"><p class="h"><b>This month</b><span>Free plan · sample</span></p><p class="mt"><span>Documents</span><i style="--w:27%"></i><b>4 of 15</b></p><p class="mt"><span>Emails today</span><i style="--w:24%"></i><b>6 of 25</b></p><p class="s">At 12 documents and again at 15 we email the owner once. Going over never bills you.</p></div>
{/if}
</div>
<style>
  .scr { background: #faf8f3; color: #1b1b1b; border-radius: 6px; padding: 18px; box-shadow: 0 30px 60px rgb(60 40 140 / 0.225); font: 500 13px/1.4 var(--font-sans); min-height: 260px; position: relative; overflow: hidden; }
  .scr :global(*) { box-sizing: border-box; } p { margin: 0; } .h4 { margin: 0 0 8px; font: 700 15px/1.2 var(--font-sans); } i { display: block; }
  .run [style*="--d"], .run .fl { animation: ins .5s cubic-bezier(.2, .8, .2, 1) both; animation-delay: var(--d); } :global(html.js) .scr:not(.run) :global([style*="--d"]) { opacity: 0; } @keyframes ins { from { opacity: 0; transform: translateY(8px); } }
  .k-fields .pg .h4 { max-width: calc(100% - 150px); }
  .k-fields { display: grid; grid-template-columns: 120px minmax(0, 1fr); gap: 16px; } .k-fields aside { display: grid; gap: 6px; align-content: start; } .k-fields aside b { font: 600 12px var(--font-mono); letter-spacing: .1em; color: #6f6b63; } .k-fields aside span { border: 1px solid #d9d5ca; border-radius: 4px; padding: 6px 8px; background: #fff; font-size: 12px; }
  .pg, .pgbox { position: relative; background: #fff; border: 1px solid #e3dfd4; border-radius: 3px; padding: 18px; min-height: 230px; } .pg i, .pgbox i { height: 6px; background: #e6e2d8; margin: 9px 0; border-radius: 2px; }
  .fl { position: absolute; border: 1.5px dashed #8a857c; border-radius: 3px; padding: 5px 7px; font: 500 10.5px/1 var(--font-mono); color: #6a665d; font-style: normal; background: rgb(0 0 0 / .02); } .fl.red { border-color: rgb(90 58 193 / 0.5); color: #4c2fb0; background: rgb(90 58 193 / 0.035); } .fl.blue { border-color: #3a5fe5; color: #2a47b8; background: rgb(58 95 229 / .07); }
  .chip { position: absolute; right: 10px; top: 8px; font: 600 10px var(--font-mono); text-decoration: none; padding: 3px 7px; border-radius: 10px; background: #ebe7ff; color: #4c2fb0; } .chip.b { right: 70px; background: #e3e8fd; color: #2a47b8; }
  .k-board .tb { display: flex; gap: 8px; align-items: center; margin-bottom: 10px; } .tb b { margin-right: auto; font-size: 15px; } .tb span { border: 1px solid #d9d5ca; border-radius: 12px; padding: 3px 10px; font-size: 12px; background: #fff; } .tb span.on { background: #1b1b1b; color: #f4f2ec; border-color: #1b1b1b; }
  .row { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr) minmax(0, 1.2fr) auto; gap: 10px; align-items: center; padding: 9px 4px; border-top: 1px solid #e6e2d8; } .row b { font-weight: 600; } .row span { color: #6f6b63; } .row button { font: 600 12px var(--font-sans); border: 1px solid #1b1b1b; background: #fff; border-radius: 4px; padding: 4px 9px; }
  .st { font-style: normal; font: 600 12px var(--font-mono); padding: 3px 8px; border-radius: 10px; width: fit-content; background: #eceae2; } .st.executed { background: #d9f0dd; color: #1f6b34; } .st.signed { background: #e3e8fd; color: #2a47b8; } .st.opened { background: #fdf0d6; color: #8a5a0b; } .st.sent { background: #eceae2; color: #4a4740; } .st.declined { background: #ece7e4; color: #5c3d33; }
  .k-phone, .k-phone-pay { display: grid; place-items: center; background: transparent; box-shadow: none; padding: 0; } .ph { width: 232px; background: #faf8f3; border: 7px solid var(--hairline); border-radius: 28px; padding: 14px 12px; display: grid; gap: 10px; box-shadow: 0 30px 60px rgb(60 40 140 / 0.225); } .ph .top { display: flex; justify-content: space-between; font-size: 12px; font-weight: 600; } .ph .top u { text-decoration: none; background: #eceae2; padding: 2px 7px; border-radius: 9px; } .ph .pg { min-height: 150px; padding: 12px; }
  .ph .ck, .ck2 { display: flex; gap: 6px; align-items: center; font-size: 12px; } .ck s, .ck2 s { width: 11px; height: 11px; border: 1.4px solid #1b1b1b; border-radius: 2px; display: inline-block; text-decoration: none; } .ph button, .em button, .fm button { background: #1b1b1b; color: #fff; border: 0; border-radius: 6px; padding: 9px; font: 600 12px var(--font-sans); } .ph button { background: #1b1b1b; }
  .em .m { padding: 6px 0; border-bottom: 1px solid #e6e2d8; } .em .m span { display: inline-block; width: 60px; color: #6f6b63; font-size: 12px; } .em .bd { padding: 16px 4px; display: grid; gap: 12px; justify-items: start; } .em .s { font-size: 12px; color: #6f6b63; }
  .em.test { position: relative; } .em .wm::after { content: attr(data-w); } .em .wm { position: absolute; right: 14px; bottom: 10px; font: 800 54px/1 var(--font-sans); color: rgb(133 133 253 / .16); transform: rotate(-14deg); letter-spacing: .06em; }
  .ct { position: relative; display: grid; gap: 8px; } .ct p:not(.h4) { display: flex; gap: 12px; padding: 7px 0; border-bottom: 1px solid #e6e2d8; } .ct p span { width: 80px; color: #6f6b63; font: 500 12px var(--font-mono); } .ct .stamp { position: absolute; right: 6px; bottom: -4px; border: 3px solid #5a3ac1; color: #5a3ac1; font: 800 20px var(--font-sans); letter-spacing: .08em; padding: 6px 12px; border-radius: 6px; transform: rotate(-12deg);  }
  .run .stamp { animation: stampin .6s 1.2s cubic-bezier(.2, .8, .2, 1) both; } @keyframes stampin { from { opacity: 0; transform: rotate(-12deg) scale(1.8); } }
  .tm .h { display: flex; justify-content: space-between; border-bottom: 1.5px solid #1b1b1b; padding: 4px 0; margin-top: 8px; } .tm .h:first-child { margin-top: 0; } .tm .h span { color: #6f6b63; font: 500 12px var(--font-mono); } .tm .row { grid-template-columns: minmax(0, 1fr) auto minmax(0, 2fr); }
  .pay { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 14px; align-items: center; border: 1.5px solid #1b1b1b; border-radius: 6px; padding: 12px 14px; margin-top: 14px; background: #fff; } .pay span { font: 700 18px var(--font-sans); } .pay u { text-decoration: none; background: #1b1b1b; color: #fff; padding: 6px 10px; border-radius: 5px; font-size: 12px; }
  .fm { display: grid; gap: 8px; max-width: 320px; } .fm .in { border: 1px solid #cfcabc; border-radius: 5px; padding: 9px 10px; color: #6f6b63; background: #fff; } .fm .to { color: #1f6b34; font-weight: 600; font-size: 12px; margin-top: 4px; }
  .sb { display: grid; gap: 10px; } .sb .ask { background: #1b1b1b; color: #f4f2ec; padding: 11px 13px; border-radius: 8px; } .ck2 { font-size: 12.5px; } .ck2 s { background: #1f6b34; border-color: #1f6b34; } .sb .bt { display: flex; gap: 10px; align-items: center; margin-top: 4px; } .sb .bt b { background: #1b1b1b; color: #f4f2ec; padding: 8px 14px; border-radius: 6px; font-size: 12px; } .sb .bt span { text-decoration: underline; font-size: 12px; }
  .au .row { grid-template-columns: 76px minmax(0, 1.6fr) minmax(0, 1fr); font-family: var(--font-mono); font-size: 12px; } .au time { color: #6f6b63; } .au b { color: #4c2fb0; font-weight: 600; }
  .lg .row { grid-template-columns: 90px minmax(0, 1fr) auto; font-size: 14px; } .lg .row[dir="rtl"] { text-align: right; }
  .us .h { display: flex; justify-content: space-between; border-bottom: 1.5px solid #1b1b1b; padding: 4px 0 6px; } .us .h span { color: #6f6b63; font: 500 12px var(--font-mono); } .us .mt { display: grid; grid-template-columns: 110px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 14px 0 4px; } .us .mt i { height: 8px; background: #e6e2d8; border-radius: 4px; position: relative; } .us .mt i::after { content: ""; position: absolute; inset: 0 auto 0 0; width: var(--w); background: #1b1b1b; border-radius: 4px; } .us .s { margin-top: 14px; color: #6f6b63; font-size: 12px; }
  @media (max-width: 560px) { .pay { grid-template-columns: minmax(0, 1fr) auto; row-gap: 8px; } .pay b { grid-column: 1 / -1; } .pay span { white-space: nowrap; } .pay u { text-align: center; } .k-fields { grid-template-columns: minmax(0, 1fr); } .k-fields aside { grid-template-columns: repeat(3, minmax(0, 1fr)); } .row { grid-template-columns: minmax(0, 1fr) auto; row-gap: 3px; } .row > * { grid-column: 1; min-width: 0; } .row button { grid-column: 2; grid-row: 1 / span 3; align-self: center; min-width: 88px; } .row span { display: block; font-size: 12.5px; overflow-wrap: anywhere; } .k-board .tb { flex-wrap: wrap; } .tb b { flex: 1 0 100%; margin: 0 0 2px; } .au .row { grid-template-columns: 62px minmax(0, 1fr); } .au .row > * { grid-column: auto; } .au .row span { display: block; grid-column: 2; } }
  @media (prefers-reduced-motion: reduce) { :global(html.js) .scr:not(.run) :global([style*="--d"]) { opacity: 1; } .run [style*="--d"], .run .fl, .run .stamp { animation: none; } }
</style>
